# 3급 CH5 대명사 (41~50) 2차 감수
X(3, 41, r="인칭대명사는 자리에 따라 형태가 달라진다. 동사·전치사 뒤에는 목적격(me, us, him, her, them), 명사 앞에는 소유격(my, our), ‘~의 것’은 소유대명사(mine, ours, theirs)를 쓴다.",
  n=["전치사 to 뒤에는 목적격 me를 써야 하므로", "‘그들의 것’은 소유대명사 theirs를 써야 하므로", "‘나의 것’은 소유대명사 mine을 써야 하므로", "동사 invited의 목적어로 목적격 us를 바르게 썼으므로", "동사 told의 목적어로 목적격 us를 써야 하므로"],
  st="① 문장마다 대명사가 놓인 자리를 본다. 주어 자리는 주격, 동사·전치사 뒤는 목적격, 명사 앞은 소유격, 명사 없이 ‘~의 것’은 소유대명사다. → ② 자리에 맞지 않는 형태를 지운다. → ③ {n}만 옳다({0}).",
  R="동사 invited 뒤에 목적격 us", B="동사 lent 뒤에 목적격 me, 명사 pen 앞에 소유격 her", C="동사 helped 뒤에 목적격 me", D="동사 called 뒤에 목적격 him", E="동사 saw 뒤에 목적격 her", F="동사 know 뒤에 목적격 them")

X(3, 42, r="this/that은 단수 명사·셀 수 없는 명사와, these/those는 복수 명사와 쓰고 동사도 그 수에 맞춘다. information, furniture, news, advice는 셀 수 없어 단수로 취급한다.",
  n=["단수 명사 flower에 This와 smells를 바르게 썼으므로", "복수 명사 boys에 Those와 are를 바르게 썼으므로", "information은 셀 수 없는 명사라 This information is로 써야 하므로", "단수 명사 movie에 That과 was를 바르게 썼으므로", "단수 명사 story에 is를 바르게 썼으므로"],
  st="① 문장마다 ‘지시어(this/that/these/those) - 명사 - 동사’ 세 가지의 수가 맞는지 본다. → ② 셀 수 없는 명사(information, furniture, news)는 단수로, 짝을 이루는 물건(pants, glasses, scissors)은 복수로 취급한다. → ③ {n}이 어긋난다: {0}.",
  R="information은 셀 수 없으므로 This information is가 맞다", B="book이 단수이므로 This book is(또는 These books are)가 맞다", C="pants는 복수 취급하므로 These pants are가 맞다", D="glasses는 복수 취급하므로 Those glasses are가 맞다",
  E="house가 단수이므로 That house is(또는 Those houses are)가 맞다", F="furniture는 셀 수 없으므로 This furniture is가 맞다")

X(3, 43, r="재귀대명사는 주어와 같은 대상을 가리킨다. 상대(you) 한 사람에게는 yourself, 여러 사람에게는 yourselves를 쓴다. help yourself to ~(마음껏 먹다), take care of yourself(몸조심하다).",
  n=["주어(you)와 목적어가 같을 때는 재귀대명사를 써야 하므로", "your는 소유격이라 목적어 자리에 쓸 수 없으므로", "yours는 ‘너의 것’이라 뜻이 맞지 않으므로", "Mom 한 사람에게 하는 말이라 yourself가 두 문장에 모두 알맞으므로", "Mom은 한 사람이라 복수형 yourselves를 쓸 수 없으므로"],
  st="① 두 문장 모두 듣는 사람(you)에게 하는 말이고, 빈칸은 그 사람 자신을 가리킨다. 재귀대명사 자리다. → ② 듣는 사람이 한 명인지 여러 명인지 부르는 말로 확인한다: {0}. → ③ 정답은 {a}.",
  R="Mom, 한 명", B="Mina, 한 명", C="Tom, 한 명", D="Children, 여러 명", E="Jane, 한 명", F="Boys, 여러 명")

X(3, 44, r="one(복수 ones)은 앞에 나온 명사와 같은 종류의 다른 것을 대신하고, it(복수 them)은 앞에 나온 바로 그것을 가리킨다.",
  n=["shoes는 복수라 one을 쓸 수 없으므로", "둘째 빈칸은 바로 그 전화기를 가리키므로 one을 쓸 수 없으므로", "첫째 빈칸은 the 뒤에서 명사를 대신해야 하므로 them을 쓸 수 없으므로", "두 빈칸 모두 맞지 않으므로", "같은 종류의 신발(복수)은 ones, 바로 그 전화기는 it이므로"],
  st="① 첫째 빈칸은 앞 명사({0})와 ‘같은 종류의 것’을 대신한다. 단수이면 one, 복수이면 ones다. → ② 둘째 빈칸은 앞에 나온 ‘바로 그것’({1})을 가리킨다. 단수이면 it, 복수이면 them이다. → ③ 정답은 {a}.",
  R=("shoes, 복수", "My phone, 단수"), B=("socks, 복수", "My gloves, 복수"), C=("bag, 단수", "My books, 복수"), D=("apples, 복수", "My keys, 복수"), E=("phone, 단수", "The laptop, 단수"), F=("chairs, 복수", "My coat and bag, 복수"))
RV(3, 44, "B", fx=True, why="수정 예시의 정답 조합(ones - it)이 원문항과 같아, 둘째 문장을 복수(My gloves)로 바꿔 ones - them이 되게 했다.")

X(3, 45, r="강조 용법의 재귀대명사는 생략할 수 있지만 목적어인 재귀대명사는 생략할 수 없다. these/those + 복수 명사. 날씨·시간·요일의 It은 비인칭 주어다. news는 단수 취급한다.",
  pre=["학생별 판정: Josh O(강조 용법이라 생략할 수 있다). Danny X(enjoyed의 목적어라 생략할 수 없다). Lisa O(These flowers). Mark X(날씨의 It은 비인칭 주어, It's my book의 It은 대명사다). Nina X(news는 단수 취급하므로 is)."],
  k="잘못 설명한 학생은 Danny, Mark, Nina다.", n=["잘못 설명한 학생은 Danny, Mark, Nina이므로"] * 5,
  st="① 학생마다 설명이 옳은지 따진다. 이 문항은 ‘잘못’ 설명한 학생을 고른다. → ② 기준: 목적어인 재귀대명사는 생략할 수 없다. 날씨·시간·요일·거리의 It은 뜻이 없는 비인칭 주어다. news, scissors 같은 명사의 수에 주의한다. → ③ {0} 잘못 설명한 학생을 모으면 {a}이다.",
  R="Danny는 enjoyed의 목적어를 생략할 수 있다고 했고, Mark는 비인칭 It과 대명사 It을 같다고 했으며, Nina는 news를 복수로 보았다.",
  B="Ben은 enjoyed의 목적어 ourselves를 생략할 수 있다고 했고, Eve는 소유대명사 hers를 목적격이라고 했다.",
  C="Jane은 This news are를 옳다고 했고, Amy는 요일의 It과 대명사 It을 같다고 했으며, Mia는 These is를 옳다고 했다.",
  D="Sam은 Help yourselves를 한 사람에게 쓴다고 했고, Amy는 목적어인 himself를 소유격이라고 했다.",
  E="Tom은 themselves를 them으로 바꿔도 같다고 했고, Ben은 This scissors is를, Leo는 are my를 옳다고 했다.",
  F="Amy는 강조 용법의 herself를 빼면 틀린다고 했고, Jane은 ourselves를 단수라고 했다.")

X(3, 46, r="요일·날짜·시간·날씨를 말할 때는 뜻이 없는 비인칭 주어 It을 쓴다(It's Wednesday.). 요일 이름: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.",
  n=["Monday는 월요일이므로", "Tuesday는 화요일이므로", "Wednesday가 수요일이므로", "Thursday는 목요일이므로", "Friday는 금요일이므로"],
  st="① 질문이 요일을 묻는지 달을 묻는지 본다({0}). → ② 괄호 속 우리말({1})에 해당하는 영어 낱말을 찾는다. 철자가 비슷한 Tuesday와 Thursday, June과 January를 헷갈리지 않는다. → ③ 정답은 {a}.",
  R=("What day → 요일", "수요일"), B=("What day → 요일", "목요일"), C=("What day → 요일", "금요일"), D=("What month → 달", "5월"), E=("What day → 요일", "월요일"), F=("What month → 달", "12월"))

X(3, 47, r="동사의 목적어 자리에는 목적격 대명사(me, us, him, her, them)를 쓴다. 주격(we), 소유격(our), 소유대명사(ours)는 쓸 수 없다.",
  n=["tell은 사람 목적어 앞에 to를 쓰지 않고 we도 주격이므로", "our는 소유격이라 목적어가 될 수 없으므로", "동사 told의 목적어로 목적격 us가 알맞으므로", "ours는 ‘우리의 것’이라 뜻이 맞지 않으므로", "to도 필요 없고 ours도 맞지 않으므로"],
  st="① 밑줄({0})은 동사({1}) 바로 뒤, 목적어 자리다. → ② 목적어 자리에는 목적격을 쓴다. 소유격·소유대명사는 쓸 수 없고, 이 동사 뒤에는 to도 필요 없다. → ③ 정답은 {a}.",
  R=("we", "told"), B=("they", "invited"), C=("she", "called"), D=("he", "saw"), E=("they", "helped"), F=("I", "gave"))
RV(3, 47, "E", fx=True, why="수정 예시의 정답(us)이 원문항 정답과 같아, 밑줄을 they로 되돌려 정답이 them이 되게 했다.")

X(3, 48, r="buy, give, tell, show, bring 같은 동사는 ‘주어 + 동사 + 사람(간접목적어) + 사물(직접목적어)’ 순서로 쓴다. 사람 자리에는 목적격을 쓴다.",
  n=["사람(me)이 사물 뒤에 놓였는데 전치사가 없으므로", "동사 + 사람(me) + 사물(a pair of shoes) 순서로 바르게 배열했으므로", "동사 bought가 My와 mother 사이에 놓였으므로", "a pair of의 순서가 뒤섞였으므로", "a pair of shoes의 순서가 틀리고 me도 맨 뒤에 놓였으므로"],
  st="① 주어({0})와 동사({1})를 먼저 놓는다. → ② 동사 뒤에는 ‘~에게’(사람)를 먼저, ‘~을’(사물)을 나중에 둔다: {2}. → ③ 이 순서인 {n}이 정답이다. 사람 자리에 주격을 쓰거나 사람을 맨 뒤에 둔 것은 틀린다.",
  R=("My mother", "bought", "me + a pair of shoes"), B=("The teacher", "told", "us + an interesting story"), C=("My father", "bought", "me + a book"), D=("Jane", "brought", "me + a glass of water"), E=("Tom", "showed", "us + a picture"),
  F=("The teacher", "gave", "them + homework"))

X(3, 49, r="재귀대명사 관용 표현: help yourself to ~(~을 마음껏 먹다), make yourself at home(편하게 있다), enjoy yourself(즐겁게 보내다), behave yourself(얌전히 행동하다).",
  n=["enjoy yourself는 ‘즐겁게 보내다’라는 뜻이므로", "take yourself라는 관용 표현은 없으므로", "help yourself to ~가 ‘~을 마음껏 먹다’라는 뜻이므로", "make yourself는 at home과 함께 ‘편하게 있다’는 뜻이므로", "eat yourself라는 관용 표현은 없으므로"],
  st="① 괄호 속 우리말과 빈칸 뒤의 말({0})을 본다. → ② 그 뜻의 재귀대명사 관용 표현을 떠올린다: {1}. → ③ 정답은 {a}.",
  R=("to anything you'd like", "help yourself to ~(마음껏 먹다)"), B=("at home", "make yourself at home(편하게 있다)"), C=("to the cake", "help yourselves to ~(마음껏 먹다)"), D=("즐거운 시간 보내!", "enjoy yourself(즐겁게 보내다)"),
  E=("inside", "behave yourselves(얌전히 행동하다)"), F=("to them", "help yourself to ~(마음껏 먹다)"))

X(3, 50, r="주어와 목적어가 같은 대상이면 목적어로 재귀대명사를 쓴다. by oneself(혼자서), make yourself at home(편하게 있다)도 재귀대명사를 쓰는 표현이다.",
  pre=["문장별 판정: ⓐ X. 주어 You와 목적어가 같으므로 yourself. ⓑ O. by himself. ⓒ O. 여러 사람(boys)에게 yourselves. ⓓ X. 주어 I와 목적어가 같으므로 myself. ⓔ O. introduce myself."],
  k="옳은 문장은 ⓑ, ⓒ, ⓔ 세 개다.", n=["옳은 문장은 ⓑ, ⓒ, ⓔ 세 개이므로"] * 5,
  st="① 문장마다 목적어가 주어와 같은 대상인지 본다. 같다면 재귀대명사(-self, -selves)를 써야 한다. → ② 재귀대명사의 형태도 확인한다. 단수는 -self, 복수는 -selves이고 themselves, ourselves가 바른 형태다. → ③ {0} 옳은 문장은 {a}이다.",
  R="ⓐ는 love yourself, ⓓ는 hurt myself로 써야 한다. 나머지 셋이 옳다.", B="ⓑ는 respect ourselves, ⓓ는 burned myself, ⓔ는 themselves로 써야 한다. ⓐ, ⓒ만 옳다.", C="ⓓ만 틀렸다. helped ourselves로 써야 한다.",
  D="ⓐ는 Help yourself, ⓑ는 themselves, ⓔ는 ourselves로 써야 한다. ⓒ, ⓓ만 옳다.", E="ⓓ만 틀렸다. The boys는 복수이므로 themselves로 써야 한다.",
  F="ⓐ는 yourself, ⓑ는 ourselves, ⓓ는 herself, ⓔ는 themselves로 써야 한다. ⓒ만 옳다.")
RV(3, 50, "DE", fx=True, why="수정 예시 D의 정답(3개, ③)이 원문항의 정답 개수·위치와 같아 2개로 바꿨고, E는 틀린 문장이 하나도 없는 5개여서 원래 변형의 틀린 문장(themself)을 되살려 4개로 했다.")
